"""
Prompt assembly from pipeline specification.
"""

from typing import Any

from .models import PromptSpec
from .variables import interpolate, resolve_variable


class Message:
    """Chat message for LLM API."""

    def __init__(self, role: str, content: str):
        self.role = role
        self.content = content

    def to_dict(self) -> dict[str, str]:
        return {"role": self.role, "content": self.content}


def assemble_prompt(spec: PromptSpec, context: dict[str, Any]) -> list[dict[str, str]]:
    """
    Assemble LLM messages from prompt spec.

    Args:
        spec: Prompt specification from pipeline config
        context: Execution context with resolved step results

    Returns:
        List of messages in OpenAI format
    """
    messages: list[Message] = []

    # System message
    system_content = ""
    if spec.system:
        system_content = interpolate(spec.system, context)

    # Context (appended to system)
    if spec.context:
        context_content = interpolate(spec.context, context)
        if system_content:
            system_content += f"\n\n{context_content}"
        else:
            system_content = context_content

    # History handling
    if spec.history:
        # Distillation as system context
        if spec.history.distillation:
            distill = interpolate(spec.history.distillation, context)
            if distill:
                if system_content:
                    system_content += f"\n\n## Conversation Summary\n{distill}"
                else:
                    system_content = f"## Conversation Summary\n{distill}"

    # Add system message if we have content
    if system_content:
        messages.append(Message("system", system_content))

    # History turns as conversation
    if spec.history and spec.history.turns:
        # Extract the variable reference from the string
        turns_ref = spec.history.turns.strip()
        if turns_ref.startswith("{") and turns_ref.endswith("}"):
            turns_ref = turns_ref[1:-1]

        turns = resolve_variable(turns_ref, context)
        if turns and isinstance(turns, list):
            for turn in turns:
                if isinstance(turn, dict):
                    user_msg = turn.get("user", "")
                    assistant_msg = turn.get("assistant", "")
                    if user_msg:
                        messages.append(Message("user", user_msg))
                    if assistant_msg:
                        messages.append(Message("assistant", assistant_msg))

    # Current message
    if spec.message:
        message_content = interpolate(spec.message, context)
        messages.append(Message("user", message_content))

    return [m.to_dict() for m in messages]

